// Edit this list to change where ideas come from (any RSS feed works)
const feeds = [
  'https://trends.google.com/trending/rss?geo=US',
  'https://www.sciencedaily.com/rss/top/science.xml',
  'https://www.reddit.com/r/todayilearned/top/.rss?t=day',
  'https://www.reddit.com/r/interestingasfuck/top/.rss?t=day'
];
return feeds.map(url => ({ json: { url } }));

const cfg = $('Config').first().json;
const headlines = $input.all()
  .map(i => i.json.title)
  .filter(t => typeof t === 'string' && t.length > 0)
  .slice(0, 80);
if (headlines.length === 0) throw new Error('No headlines: every feed failed. Check the Read feeds node.');
const prompt = `You are the research brain of a short-video channel about: ${cfg.niche}.
Today's trending headlines:
- ${headlines.join('\n- ')}

Propose exactly ${cfg.ideasPerDay} ideas for 30-60 second vertical videos in ${cfg.language}.
Pick ideas that fit the niche, are evergreen or trending, and can be shown with visuals.
Return ONLY a JSON array. Each item: {"title": string, "hook": string (first sentence, max 15 words, creates curiosity), "angle": string (one sentence), "source_headline": string, "score": number 0-100 (viral potential), "lane": "stock" if real-world footage can show it, or "ai" if it needs imaginary/impossible visuals}.`;
return [{ json: { prompt } }];

const text = $json.candidates?.[0]?.content?.parts?.[0]?.text || '[]';
let ideas = JSON.parse(text);
if (!Array.isArray(ideas)) ideas = ideas.ideas || [];
const records = ideas.map(i => ({
  Title: String(i.title || '').slice(0, 250),
  Hook: i.hook || '',
  Angle: i.angle || '',
  Source: i.source_headline || '',
  Score: Number(i.score) || 0,
  Lane: i.lane === 'ai' ? 'ai' : 'stock',
  Status: 'new'
})).filter(r => r.Title);
if (records.length === 0) throw new Error('Gemini returned no ideas: ' + text.slice(0, 300));
return [{ json: { records } }];
